/** autogenerated **/
Ext._define('rh.pvf.waitingapproval.Manage', {
    extend: 'toolkit.widget.TabPanel',

    getWaitingApprovalGrid: function(cfg) {
        if(!this._grid) {
            this._grid = Ext._create('rh.pvf.waitingapproval.Grid', {
                region: 'center',
                gridAutoLoad: false,
                columnAction: false,
                allowCreate: false,
                allowUpdate: false,
                allowRemove: false,
                filter_employee:cfg.filter_employee,
                filter_status:JSON.parse(cfg.filter_status.replaceAll("'",'"')),
                type_employee:cfg.type_employee

    
            });

            this._grid.getStore().reload()


        }
    
        return this._grid;
    },


    getEmployeeGrid: function (cfg) {
        if (!this._employeeGrid) {
            this._employeeGrid = Ext._create('rh.pvf.employee.Grid', {
                region: 'west',
                width: '25%',
                maxWidth: '25%',
                minWidth: '25%',
                split: true,
                columnAction: false,
                allowCreate: false,
                allowUpdate: false,
                allowRemove: false,
                onlyColumns: [
                    'matricula',
                    'pessoa_fisica_unicode',
                ],
                configOrderToolBar: ['search'],
                gridAutoLoad: false
            });
            
            // if (cfg.group_dgp){
            //     this._employeeGrid.setFilterProperty('portal_request_employee__step_current__in',group_all,6000,false)
            // }

            this._employeeGrid.setFilterProperty('ativo', true,6001)


            this._employeeGrid.getSelectionModel().on({
                scope: this,
                rowselect: function (sm, index, record) {
                    this.employee(record.get('pk'));
                },
                rowdeselect: function (sm) {
                    this.employee(null);
                }
            });


        }

        return this._employeeGrid;
    },

    employee: function (value, prevent) {
        prevent = core.nullValue(prevent, false);

        if (value !== undefined) {
            this._employee = value;

            !prevent && this.employeeObserver();
        }

        return this._employee;
    },

    employeeObserver: function () {
        var value = this.employee();
        if(value) {
            this.getWaitingApprovalGrid().enable();
            this.getWaitingApprovalGrid().setFilterProperty('employee',value,1005)

        }
        else {
            this.getWaitingApprovalGrid().getStore().removeAll();
        }
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});
        
        group_all = cfg.group_all.replaceAll("'",'"');
        group_all = JSON.parse(group_all)

        status_hidden = cfg.status_hidden.replaceAll("'",'"');
        status_hidden = JSON.parse(status_hidden)

        Ext.applyIf(
            cfg,
            {
                title: 'Aguardando Aprovação/Ciência'
            }
        );

        Ext.apply(
            cfg,
            {
                layout: 'border',
                items: [
                    this.getWaitingApprovalGrid(cfg),
                    this.getEmployeeGrid(cfg),
                    
                ]
            }
        );
        
        rh.pvf.waitingapproval.Manage.superclass.constructor.call(this, cfg);
        this.getWaitingApprovalGrid(cfg).setParam('employee_grid',this.getEmployeeGrid())
        this.getWaitingApprovalGrid(cfg).setParam('group_all',group_all)
        this.getWaitingApprovalGrid(cfg).setParam('status_hidden',status_hidden)
        this.getWaitingApprovalGrid(cfg).setParam('group_dgp',cfg.group_dgp)
        this.getWaitingApprovalGrid(cfg).setParam('employee_id',cfg.employee_id)
        this.getWaitingApprovalGrid(cfg).setParam('group_progression',cfg.group_progression)
        this.employeeObserver()
    }
});
